import{_ as a,V as e,W as c,a0 as t}from"./framework-9a29aaa0.js";const l={},r=t('<ul><li><a href="#blockstack%E4%B8%80%E4%B8%AA%E7%94%B1%E5%8C%BA%E5%9D%97%E9%93%BE%E4%BF%9D%E9%9A%9C%E7%9A%84%E5%85%A8%E7%90%83%E5%91%BD%E5%90%8D%E4%B8%8E%E5%AD%98%E5%82%A8%E7%B3%BB%E7%BB%9F">BlockStack：一个由区块链保障的全球命名与存储系统</a><ul><li><a href="#%E6%91%98%E8%A6%81">摘要</a></li><li><a href="#1%E5%BC%95%E8%A8%80">1.引言</a></li></ul></li></ul><h1 id="blockstack-一个由区块链保障的全球命名与存储系统" tabindex="-1"><a class="header-anchor" href="#blockstack-一个由区块链保障的全球命名与存储系统" aria-hidden="true">#</a> BlockStack：一个由区块链保障的全球命名与存储系统</h1><h2 id="摘要" tabindex="-1"><a class="header-anchor" href="#摘要" aria-hidden="true">#</a> 摘要</h2><p>在过去几年里，像比特币和域名币这样的区块链及其各自的点对点网络已得到了广泛应用，并有望成为无需可信方的命名系统。用户可以注册有人类可读意义的名称，并将数据与之安全关联，而且只有注册该名称的特定私钥的所有者才能写入或更新名称 - 值对。从理论上讲，可以利用这些区块链网络构建许多去中心化系统，比如域名系统（DNS）和公钥基础设施（PKI）的新型去中心化版本。然而，由于这项技术相对较新且发展迅速，可用于指导设计权衡的实际生产数据或经验非常少。</p><p>在本文中，我们将介绍在基于域名币区块链搭建的去中心化公钥基础设施（PKI）服务大规模部署过程中的相关经验。在域名币区块链上注册和更新超过 33,000 个条目以及 200,000 笔交易时，我们遇到了与网络可靠性、吞吐量以及安全性相关的诸多挑战，对此我们也将阐述是如何克服这些挑战的。</p><p>此外，我们还将讨论这些经验是如何为一个名为块栈（Blockstack）的全新基于区块链的命名与存储系统的设计提供参考的。我们会详细说明在新系统中为何从域名币网络切换到比特币网络，并介绍此次迁移过程中的一些运营经验教训。BlockChain作为开源软件发布，目前为 55,000 名用户的生产公钥基础设施系统提供支持。</p><h2 id="_1-引言" tabindex="-1"><a class="header-anchor" href="#_1-引言" aria-hidden="true">#</a> 1.引言</h2><p>加密货币区块链及其各自的点对点网络的用途不止于货币交易。它们提供了可进行密码学审计且仅能追加记录的账本，这些账本已被用于构建域名系统（DNS）和公钥基础设施（PKI）的新型去中心化版本，以及其他应用，如文件存储和文件时间戳标注。</p><p>由于区块链不存在信任或故障的中心点，它们催生了一类新的去中心化应用和服务，这类应用和服务将用户对单一主体（如域名系统根服务器或根证书颁发机构）的信任需求程度降至最低。</p>',9),o=[r];function s(h,i){return e(),c("div",null,o)}const E=a(l,[["render",s],["__file","lesson20-block-stack-paper.html.vue"]]);export{E as default};
